import * as THREE from 'three';
import { Configurator } from '.';

import { ExoSkeletonMeshes } from './Parts/ExoSkeletonMeshes';
import { Skeleton } from './Parts/Skeleton';

export class HypercubeParametric {
	public configurator: Configurator;

	public exoSkeletonMeshes: ExoSkeletonMeshes;

	public skeleton: Skeleton;

	public col = [];
	constructor(configurator: Configurator) {
		this.configurator = configurator;
		this.init();
	}
	public init() {
		let t0 = performance.now();

		// this.skeleton = new Skeleton(this);

		let t1 = performance.now();
		// console.log(`took ${t1 - t0} milliseconds.`);

		t0 = performance.now();
		this.exoSkeletonMeshes = new ExoSkeletonMeshes(this);
		this.exoSkeletonMeshes.setWidth(this.configurator.dimension.width);
		this.exoSkeletonMeshes.setLength(this.configurator.dimension.length);

		t1 = performance.now();
		// console.log(`took ${t1 - t0} milliseconds.`);
	}

	public toggleXrayParametricModel(value: boolean) {
		if (this.exoSkeletonMeshes) {
			this.exoSkeletonMeshes.columns.forEach((obj: THREE.Mesh) => {
				obj.material.transparent = value;
				obj.material.depthWrite = !value;
				obj.material.opacity = value ? 0.2 : 1.0;
				obj.material.needsUpdate = true;

				obj.castShadow = !value;
				obj.receiveShadow = !value;
			});

			this.exoSkeletonMeshes.bars.forEach((obj: THREE.Mesh) => {
				obj.material.transparent = value;
				obj.material.depthWrite = !value;
				obj.material.opacity = value ? 0.2 : 1.0;
				obj.material.needsUpdate = true;

				obj.castShadow = !value;
				obj.receiveShadow = !value;
			});
		}

		if (this.skeleton) {
			this.skeleton.resultMesh.material.transparent = value;
			this.skeleton.resultMesh.material.depthWrite = !value;
			this.skeleton.resultMesh.material.opacity = value ? 0.2 : 1.0;
			this.skeleton.resultMesh.material.needsUpdate = true;

			this.skeleton.resultMesh.castShadow = !value;
			this.skeleton.resultMesh.receiveShadow = !value;
		}
	}
}
