import { getSlider, getCheckBox } from '../utils';

import { View } from '.';
import { ENVIRONMENT_TYPE } from '../utils/const';
export class UILeftSandbox {
	public view: View;
	public width!: string;
	public divUILeft!: HTMLDivElement;
	public color!: string;
	constructor(view: View) {
		this.view = view;
	}
	public init() {
		const divBtForward = document.createElement('button');
		this.divUILeft.appendChild(divBtForward);
		divBtForward.style.width = this.width;
		divBtForward.textContent = 'changing views forward';
		divBtForward.style.fontSize = '11px';
		divBtForward.onclick = () => {
			this.view.solution.appCore.common.viewChangingForward();
		};

		const divBtBackward = document.createElement('button');
		this.divUILeft.appendChild(divBtBackward);
		divBtBackward.style.width = this.width;
		divBtBackward.textContent = 'changing views backward';
		divBtBackward.style.fontSize = '11px';
		divBtBackward.onclick = () => {
			this.view.solution.appCore.common.viewChangingBackward();
		};

		const sliderFOV = getSlider('FOV', 20, 50);
		this.divUILeft.appendChild(sliderFOV.div);
		sliderFOV.slider.oninput = () => {
			const value = parseInt(sliderFOV.slider.value);
			this.view.solution.appCore.common.changeFOV(value);

			sliderFOV.text.textContent = `FOV: ${value}`;
		};

		if (this.view.solution.environmentType === ENVIRONMENT_TYPE.Configurator && this.view.solution.appCore.sceneWrapper.configurator) {
			this.uiConfigurator();
		} else {
			this.uiSandbox();
		}
	}
	public uiConfigurator() {
		// const divBtnHideAll = document.createElement('button');
		// this.divUILeft.appendChild(divBtnHideAll);
		// divBtnHideAll.style.width = this.width;
		// divBtnHideAll.style.marginTop = '15px';
		// divBtnHideAll.textContent = 'Hide All';
		// divBtnHideAll.style.fontSize = this.view.fontSize;
		// divBtnHideAll.onclick = () => {
		// 	this.view.solution.appCore.common.hideAll();
		// 	this.view.solution.appCore.common.showHypercube();
		// };

		let isStudioVisible = true;
		const divBtnShowStudio = document.createElement('button');
		this.divUILeft.appendChild(divBtnShowStudio);
		divBtnShowStudio.style.marginTop = '15px';
		divBtnShowStudio.style.width = this.width;
		divBtnShowStudio.textContent = 'Show/Hide HC Static model';
		divBtnShowStudio.style.fontSize = '10px';
		divBtnShowStudio.onclick = () => {
			if (isStudioVisible) {
				this.view.solution.appCore.common.showHypercubeStatic();
			} else {
				this.view.solution.appCore.common.hideHypercubeStatic();
			}
			isStudioVisible = !isStudioVisible;
		};

		const min = 10;
		const max = 50;
		const initParam = this.view.solution.appCore.sceneWrapper.configurator.dimension;
		const step = 0.1;

		const sliderWidth = getSlider('Width', min, max, step, initParam.width);
		this.divUILeft.appendChild(sliderWidth.div);
		sliderWidth.slider.oninput = () => {
			const value = parseFloat(sliderWidth.slider.value);
			// console.log(value);
			this.view.solution.appCore.common.setWidthParametricHC(value);
		};

		const sliderLength = getSlider('Length', min, max, step, initParam.length);
		this.divUILeft.appendChild(sliderLength.div);
		sliderLength.slider.oninput = () => {
			const value = parseFloat(sliderLength.slider.value);
			// console.log(value);
			this.view.solution.appCore.common.setLengthParametricHC(value);
		};

		const sliderHeight = getSlider('Height', min, max, step, initParam.height);
		this.divUILeft.appendChild(sliderHeight.div);
		sliderHeight.slider.oninput = () => {
			const value = parseFloat(sliderHeight.slider.value);
			// console.log(value);
			this.view.solution.appCore.common.setHeightParametricHC(value);
		};

		const sliderSkeletonSize = getSlider('Skeleton size', 1, 5, step, initParam.thickness);
		this.divUILeft.appendChild(sliderSkeletonSize.div);
		sliderSkeletonSize.slider.oninput = () => {
			const value = parseFloat(sliderSkeletonSize.slider.value);
			// console.log(value);
			this.view.solution.appCore.common.setSizeSkeletonParametricHC(value);
		};

		const sliderRadiusCamera = getSlider('Camera size', 0.5, 2, step, initParam.radiusCamera);
		this.divUILeft.appendChild(sliderRadiusCamera.div);
		sliderRadiusCamera.slider.oninput = () => {
			const value = parseFloat(sliderRadiusCamera.slider.value);
			// console.log(value);
			this.view.solution.appCore.common.setSizeCameraHC(value);
		};

		let xRayMode = true;
		const divBtnXRayMode = document.createElement('button');
		this.divUILeft.appendChild(divBtnXRayMode);
		divBtnXRayMode.style.marginTop = '15px';
		divBtnXRayMode.style.width = this.width;
		divBtnXRayMode.textContent = 'Show/Hide X-Ray';
		divBtnXRayMode.style.fontSize = '10px';
		divBtnXRayMode.onclick = () => {
			// if (xRayMode) {
			this.view.solution.appCore.common.toggleXrayParametricModel(xRayMode);
			// } else {
			// 	this.view.solution.appCore.common.hideHypercubeStatic();
			// }
			xRayMode = !xRayMode;
		};

		const sliderYSlipping = getSlider('Clipping Y', -20, 30, step, initParam.thickness);
		this.divUILeft.appendChild(sliderYSlipping.div);
		sliderYSlipping.slider.oninput = () => {
			const value = parseFloat(sliderYSlipping.slider.value);
			this.view.solution.appCore.common.setClippingYParametricHC(value);
		};

		const sliderXSlipping = getSlider('Clipping X', -20, 30, step, initParam.thickness);
		this.divUILeft.appendChild(sliderXSlipping.div);
		sliderXSlipping.slider.oninput = () => {
			const value = parseFloat(sliderXSlipping.slider.value);
			this.view.solution.appCore.common.setClippingXParametricHC(value);
		};
		const sliderZSlipping = getSlider('Clipping Z', -20, 30, step, initParam.thickness);
		this.divUILeft.appendChild(sliderZSlipping.div);
		sliderZSlipping.slider.oninput = () => {
			const value = parseFloat(sliderZSlipping.slider.value);
			this.view.solution.appCore.common.setClippingZParametricHC(value);
		};
	}
	public uiSandbox() {
		// .......... show and hide scene

		const divBtnHideAll = document.createElement('button');
		this.divUILeft.appendChild(divBtnHideAll);
		divBtnHideAll.style.width = this.width;
		divBtnHideAll.style.marginTop = '15px';
		divBtnHideAll.textContent = 'Hide All';
		divBtnHideAll.style.fontSize = this.view.fontSize;
		divBtnHideAll.onclick = () => {
			this.view.solution.appCore.common.hideAll();
			this.view.solution.appCore.common.showHypercube();
		};

		const divBtnShowStudio = document.createElement('button');
		this.divUILeft.appendChild(divBtnShowStudio);
		divBtnShowStudio.style.width = this.width;
		divBtnShowStudio.textContent = 'Show Studio Env';
		divBtnShowStudio.style.fontSize = this.view.fontSize;
		divBtnShowStudio.onclick = () => {
			this.view.solution.appCore.common.showStudioEnv();
		};

		const divBtnSubstation = document.createElement('button');
		this.divUILeft.appendChild(divBtnSubstation);
		divBtnSubstation.style.width = this.width;
		divBtnSubstation.textContent = 'Show Substation';
		divBtnSubstation.style.fontSize = this.view.fontSize;
		divBtnSubstation.onclick = () => {
			this.view.solution.appCore.common.showSubstation();
		};

		const divBtnSubstationDioram = document.createElement('button');
		this.divUILeft.appendChild(divBtnSubstationDioram);
		divBtnSubstationDioram.style.width = this.width;
		divBtnSubstationDioram.textContent = 'Show Diorama Style';
		divBtnSubstationDioram.style.fontSize = this.view.fontSize;
		divBtnSubstationDioram.onclick = () => {
			this.view.solution.appCore.common.showSubstationDiorama();
		};

		// ..........

		const latSlider = getSlider('lat', -90, 90);
		this.divUILeft.appendChild(latSlider.div);
		latSlider.slider.oninput = () => {
			const value = parseInt(latSlider.slider.value);
			this.view.solution.appCore.common.solar.latitude = value;
			this.view.solution.appCore.common.getSunVec(
				this.view.solution.appCore.common.solar.latitude,
				this.view.solution.appCore.common.solar.longitude,
				this.view.solution.appCore.common.solar.day,
				this.view.solution.appCore.common.solar.hour
			);
			// console.log(value);
		};

		const longSlider = getSlider('Lng', -180, 180);
		this.divUILeft.appendChild(longSlider.div);
		longSlider.slider.oninput = () => {
			const value = parseInt(longSlider.slider.value);
			this.view.solution.appCore.common.solar.latitude = value;
			this.view.solution.appCore.common.getSunVec(
				this.view.solution.appCore.common.solar.latitude,
				this.view.solution.appCore.common.solar.longitude,
				this.view.solution.appCore.common.solar.day,
				this.view.solution.appCore.common.solar.hour
			);
			// console.log(value);
		};

		const daySlider = getSlider('Day', 1, 365);
		this.divUILeft.appendChild(daySlider.div);
		daySlider.slider.oninput = () => {
			const value = parseInt(daySlider.slider.value);
			this.view.solution.appCore.common.solar.day = value;
			this.view.solution.appCore.common.getSunVec(
				this.view.solution.appCore.common.solar.latitude,
				this.view.solution.appCore.common.solar.longitude,
				this.view.solution.appCore.common.solar.day,
				this.view.solution.appCore.common.solar.hour
			);
			// console.log(value);
		};

		const hourSlider = getSlider('Hour', 10, 20);
		this.divUILeft.appendChild(hourSlider.div);
		hourSlider.slider.oninput = () => {
			const value = parseInt(hourSlider.slider.value);
			this.view.solution.appCore.common.solar.hour = value;
			this.view.solution.appCore.common.getSunVec(
				this.view.solution.appCore.common.solar.latitude,
				this.view.solution.appCore.common.solar.longitude,
				this.view.solution.appCore.common.solar.day,
				this.view.solution.appCore.common.solar.hour
			);
			// console.log(value);
		};

		const divDrone = document.createElement('button');
		this.divUILeft.appendChild(divDrone);
		divDrone.style.width = this.width;
		divDrone.style.marginTop = '10px';
		divDrone.textContent = 'Running Drone Device...';
		divDrone.style.fontSize = this.view.fontSize;
		divDrone.onclick = () => {
			this.view.solution.appCore.common.runningDroneDevices = !this.view.solution.appCore.common.runningDroneDevices;
		};

		const angleSolarPanel = getSlider('Degree', 0, 20);
		angleSolarPanel.slider.defaultValue = '0';
		this.divUILeft.appendChild(angleSolarPanel.div);
		angleSolarPanel.slider.oninput = () => {
			const value = parseInt(angleSolarPanel.slider.value);
			this.view.solution.appCore.common.angleSolarPanel(value);
		};

		const divDecompose = document.createElement('button');
		this.divUILeft.appendChild(divDecompose);
		divDecompose.style.width = this.width;
		divDecompose.style.marginTop = '5px';
		divDecompose.textContent = 'Decompose';
		divDecompose.style.fontSize = this.view.fontSize;
		divDecompose.onclick = () => {
			this.view.solution.appCore.common.decompose();
		};

		const divAnimationRotatingA = document.createElement('button');
		this.divUILeft.appendChild(divAnimationRotatingA);
		divAnimationRotatingA.style.width = this.width;
		divAnimationRotatingA.style.marginTop = '10px';
		divAnimationRotatingA.textContent = 'Animation A';
		divAnimationRotatingA.style.fontSize = this.view.fontSize;
		divAnimationRotatingA.onclick = () => {
			this.view.solution.appCore.common.toggleAnimationRotatingA();
		};

		const divAnimationRotatingB = document.createElement('button');
		this.divUILeft.appendChild(divAnimationRotatingB);
		divAnimationRotatingB.style.width = this.width;
		divAnimationRotatingB.textContent = 'Animation B';
		divAnimationRotatingB.style.fontSize = this.view.fontSize;
		divAnimationRotatingB.onclick = () => {
			this.view.solution.appCore.common.toggleAnimationRotatingB();
		};

		const divBt3 = document.createElement('button');
		this.divUILeft.appendChild(divBt3);
		divBt3.style.width = this.width;
		divBt3.textContent = 'Shifting HDRI';
		divBt3.style.marginTop = '10px';
		divBt3.style.fontSize = this.view.fontSize;
		divBt3.onclick = () => {
			this.view.solution.appCore.common.hdriChanging();
		};

		const divCastShadow = document.createElement('button');
		this.divUILeft.appendChild(divCastShadow);
		divCastShadow.style.width = this.width;
		divCastShadow.textContent = 'Activate Shadow';
		divCastShadow.style.fontSize = this.view.fontSize;
		divCastShadow.onclick = () => {
			this.view.solution.appCore.common.toggleShadow();
		};

		const divPostProcessing = document.createElement('button');
		this.divUILeft.appendChild(divPostProcessing);
		divPostProcessing.style.width = this.width;
		divPostProcessing.textContent = 'Bloom & DOF';
		divPostProcessing.style.fontSize = this.view.fontSize;
		divPostProcessing.onclick = () => {
			this.view.solution.appCore.common.toggleEffect();
		};

		const divAdaptiveRendering = document.createElement('button');
		this.divUILeft.appendChild(divAdaptiveRendering);
		divAdaptiveRendering.style.width = this.width;
		divAdaptiveRendering.textContent = 'Adaptive Rendering loop';
		divAdaptiveRendering.style.fontSize = this.view.fontSize;
		divAdaptiveRendering.onclick = () => {
			this.view.solution.appCore.common.toggleAdaptiveRendering();
		};

		const divWebGPUEnabled = document.createElement('button');
		this.divUILeft.appendChild(divWebGPUEnabled);
		divWebGPUEnabled.style.width = this.width;
		divWebGPUEnabled.textContent = 'WebGPU enabled';
		divWebGPUEnabled.style.fontSize = this.view.fontSize;
		divWebGPUEnabled.onclick = () => {
			// this.view.solution.appCore.common.toggleWebGPU();
		};

		this.appendDebugger();
	}
	public appendDebugger() {
		const divTitleDebugger = document.createElement('div');
		divTitleDebugger.textContent = 'Debuggers';
		divTitleDebugger.style.fontSize = '14px';
		divTitleDebugger.style.color = this.color;
		divTitleDebugger.style.paddingTop = '14px';
		this.divUILeft.appendChild(divTitleDebugger);

		const divDecompose = document.createElement('button');
		this.divUILeft.appendChild(divDecompose);
		divDecompose.style.width = this.width;
		divDecompose.textContent = 'Print camera positions';
		divDecompose.style.fontSize = this.view.fontSize;
		divDecompose.onclick = () => {
			this.view.solution.appCore.common.printCameraInfo();
		};

		const min = -100000;
		const max = 100000;
		const scale = 0.1;
		const debuggerX = getSlider('X', min, max);
		debuggerX.slider.defaultValue = '0.0';
		this.divUILeft.appendChild(debuggerX.div);
		debuggerX.slider.oninput = () => {
			const value = parseFloat(debuggerX.slider.value) * scale;
			this.view.solution.appCore.common.debuggerX(value);
		};
		const debuggerY = getSlider('Y', min, max);
		debuggerY.slider.defaultValue = '0.0';
		this.divUILeft.appendChild(debuggerY.div);
		debuggerY.slider.oninput = () => {
			const value = parseFloat(debuggerY.slider.value) * scale;
			this.view.solution.appCore.common.debuggerY(value);
		};
		const debuggerZ = getSlider('Z', min, max);
		debuggerZ.slider.defaultValue = '0.0';
		this.divUILeft.appendChild(debuggerZ.div);
		debuggerZ.slider.oninput = () => {
			const value = parseFloat(debuggerZ.slider.value) * scale;
			this.view.solution.appCore.common.debuggerZ(value);
		};

		let minParam = -100;
		let maxParam = 100;
		let scaleParam = 0.01;
		const debuggerA = getSlider('roughness', minParam, maxParam);
		debuggerA.slider.defaultValue = '0.0';
		this.divUILeft.appendChild(debuggerA.div);
		debuggerA.slider.oninput = () => {
			const value = parseFloat(debuggerA.slider.value) * scaleParam;
			this.view.solution.appCore.common.roughness(value);
		};
		const debuggerB = getSlider('metalness', minParam, maxParam);
		debuggerB.slider.defaultValue = '0.0';
		this.divUILeft.appendChild(debuggerB.div);
		debuggerB.slider.oninput = () => {
			const value = parseFloat(debuggerB.slider.value) * scaleParam;
			this.view.solution.appCore.common.metalness(value);
		};

		minParam = -2000;
		maxParam = 2000;
		scaleParam = 0.01;

		const debuggerC = getSlider('A', minParam, maxParam);
		debuggerC.slider.defaultValue = '0.0';
		this.divUILeft.appendChild(debuggerC.div);
		debuggerC.slider.oninput = () => {
			const value = parseFloat(debuggerC.slider.value) * scaleParam;
			this.view.solution.appCore.common.debuggerC(value);
		};
	}
}
